'use strict';
const fs=require('node:fs'),path=require('node:path'),Module=require('node:module'),crypto=require('node:crypto');
const PROGRAM=path.resolve(__dirname,'../..');
const BASE=process.env.LIB_BASE_PROGRAM||PROGRAM;
function loadServer(){const file=path.join(PROGRAM,'server/server.cjs'),m=new Module(file,module);m.filename=file;m.paths=Module._nodeModulePaths(path.dirname(file));const original=m.require.bind(m);m.require=id=>{if(id==='node:worker_threads'){const w=require(id);return {...w,Worker:class extends w.Worker{constructor(file,opts){super(fs.existsSync(file)?file:path.join(BASE,'server',path.basename(file)),opts);const hook=globalThis.__repairBackupWorkerHook;if(hook)this.prependListener('message',hook)}}};}if(id.startsWith('.')){const target=path.resolve(path.dirname(file),id);if(!fs.existsSync(target))return require(path.resolve(BASE,'server',id));}return original(id)};m._compile(fs.readFileSync(file,'utf8'),file);return m.exports;}
const hash=s=>{let h=0x811c9dc5;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),0x01000193);return(h>>>0).toString(36)};
const digest=v=>crypto.createHash('sha256').update(JSON.stringify(v)).digest('hex');
const scope='char:chat:persona',alias=hash(scope),prefix=`vector_rag_memory:scope:${alias}:`,vectorKey=`vector_rag_memory:local-vector-shard:v1:${alias}:original:0000`,owner={namespace:'flashback',roles:['owner']};
function payload(){const floats=new Float32Array([1,0,0,0,1,0]),items=[{recordId:'r1',offset:0,length:3},{recordId:'r2',offset:3,length:3}],data=Buffer.from(floats.buffer).toString('base64');return {schema:'flashback_memory.local_vector_shard.v1',version:1,scopeKey:scope,commitId:'original',shardIndex:0,itemCount:2,floatCount:6,byteLength:24,items,data,digest:hash(JSON.stringify({scopeKey:scope,commitId:'original',shardIndex:0,items,data})),createdAt:'2026-10-06T00:00:00.000Z'};}
function open(dir){const app=loadServer().createMemorySuiteServer({dataDir:dir,autoBackup:false,computeEnabled:false,token:'synthetic-offline-token-0000000000000000'});return {app,repo:app.repositories.flashback};}
function seed(repo){const p=payload(),records=p.items.map((item,index)=>({id:item.recordId,scopeKey:scope,text:'PRIVATE_RAW_SOURCE_'+index,sourceHash:'source'+index,lineage:{original:'never change'},vector:[],dim:item.length,embeddingModel:'synthetic',vectorRef:{schema:'flashback_memory.local_vector_ref.v1',storage:'local',storageKey:vectorKey,...item,digest:p.digest,mode:'local_float32_shard_v1'}}));for(const [key,value] of [[prefix+'manifest:v2',JSON.stringify({schema:'vector_rag_memory.scope_manifest.v2',scopeKey:scope,commitId:'original',shardCount:1,count:2,archiveRef:null})],[prefix+'records:commit:original:shard:0000',JSON.stringify({version:2,scopeKey:scope,commitId:'original',shard:0,records})]])repo.mutate({kind:'set',space:'plugin',key,value,operationId:'seed_'+hash(key)+'_00000000'});return {p,records};}
module.exports={BASE,PROGRAM,loadServer,hash,digest,scope,alias,prefix,vectorKey,owner,payload,open,seed};
function backup(repo,dir,binding,p=payload()){
 const backupId='synthetic_bound_backup_00001',root=path.join(dir,'backups'),folder=path.join(root,'manual',backupId);fs.mkdirSync(folder,{recursive:true});
 const old=repo.database.prepare('SELECT * FROM kv WHERE space=? AND key=?').get('local',vectorKey),json=JSON.stringify(p);
 repo.database.prepare('INSERT OR REPLACE INTO kv(space,key,value_json,deleted,revision,digest,updated_at) VALUES(?,?,?,?,?,?,?)').run('local',vectorKey,json,0,1,digest(p),0);
 const file=path.join(folder,'flashback.sqlite');try{repo.database.exec("VACUUM INTO '"+file.replace(/'/g,"''")+"'");}finally{repo.database.prepare('DELETE FROM kv WHERE space=? AND key=?').run('local',vectorKey);if(old)repo.database.prepare('INSERT INTO kv(space,key,value_json,deleted,revision,digest,updated_at) VALUES(?,?,?,?,?,?,?)').run(old.space,old.key,old.value_json,old.deleted,old.revision,old.digest,old.updated_at);}
 const contract='memory-suite.physical-data-identity.v1',manifest={schema:'memory-suite.backup.v1',id:backupId,kind:'manual',createdAtMs:Date.now(),backupRepairAuthority:{schema:'memory-suite.backup-repair-authority.v1',dataInstanceId:binding.dataInstanceId,dataIdentityContract:contract,resetEpochs:{flashback:binding.epoch}},stores:{flashback:{file:'flashback.sqlite',sha256:crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex'),bytes:fs.statSync(file).size}}};
 fs.writeFileSync(path.join(folder,'manifest.json'),JSON.stringify(manifest));
 const list=()=>[{...JSON.parse(fs.readFileSync(path.join(folder,'manifest.json'),'utf8')),path:folder}];
 let actualIdentity={dataInstanceId:binding.dataInstanceId,dataIdentityContract:contract};
 const provider=require(path.join(PROGRAM,'server/core/flashback-server-vector-proof.cjs'))({resolveBackupById:id=>id===backupId?{id:backupId,kind:'manual',path:folder}:null,backupRoot:root,dataInstanceId:binding.dataInstanceId,dataIdentityContract:contract,epochs:()=>({flashback:binding.epoch}),readIdentity:()=>actualIdentity});return {backupId,root,folder,file,manifest,list,provider,setIdentity:value=>{actualIdentity=value;}};
}
module.exports.backup=backup;
